function recoverTree(root) {
  const a = []; const go = (n) => { if (!n) return; go(n.left); a.push(n); go(n.right); };
  go(root);
  const s = a.map(n => n.val).sort((x, y) => x - y);
  a.forEach((n, i) => { n.val = s[i]; });
}
